head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");

//#include("../js/controlResize.js"); // 화면 리사이징

scwin.gIsurCd;
scwin.gSeq;
scwin.gDate;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.vScrenID = 'ULDSTF39000.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;
    $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);

    /*
		if (gLdMktTp == '1' || gLdMktTp=='2' || gLdMktTp=='6' ) {	// 코넥스 시장 추가 20130520 LDJ
grd_Grid.setColumnProp("MKT_NM", "Show",false) ;
			showObj(panel_mkt, false);
		}
		*/

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();

    // 유가일때만 초기 검색함
    //if (js_market == '1' ) {		
    //	fn_CheckCond();
    //}


    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !사외이사--;
클릭-- > function() {
    //gDepCd =  getObjectValue(cmb_TeamList);
    //gEmpNo =  getObjectValue(cmb_EmpList);

    fn_Search();
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !사외이사--;
클릭-- > function() {
    var outDirNm = txb_OutDirNm.getValue();
    var url_list = "/OutDir.do?method=listOutDirDscl&inputMessageId=OUTDIRLIST_IN" + "&outputMessageId=OUTDIRLIST_OUT";
    var url_cond = "&ISUR_NM_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&OUTDIR_NM=" + outDirNm + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // 그리드의 데이타 조회
    dts_OutDirlList.DataID = encodeURI(url_list + url_cond);
    dts_OutDirlList.reset();
    $c.cm.ShowWin(grd_Grid);
};





// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gIsurCd = dts_OutDirlList.getCellData(eval(obj), "ISUR_CD");
    scwin.gSeq = dts_OutDirlList.getCellData(eval(obj), "SEQ");
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "OUTDIR_NM") {
        var url = "/dsclmgt/ULDSTF39001.gfm";
        var winTitle = "사외이사 정보";
        //frame.CreateFrame("UDLSTF39001", url , winTitle ,200, 100, 500, 280, "window" , 0, 0, true);	
        await $c.frame.CreateDialogFrame("UDLSTF39001", url, winTitle, 200, 100, 500, 280, "window");
    }
};
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};
scwin.dts_OutDirlList_OnLoadError = function() {
    $c.stf.alert_error(dts_OutDirlList);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_OutDirlList_OnLoadCompleted = function(rowcount) {
    if (dts_OutDirlList.errorMsg) {
        $c.win.alert(dts_OutDirlList.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_emp_OnLoadError = function() {
    $c.stf.alert_error(dts_emp);
};
scwin.dts_dep_OnLoadError = function() {
    $c.stf.alert_error(dts_dep);
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    // 유가일때만 디폴트 로그인한 사용자	

    //if (js_market == '1' ) {

    //	setObjectValue(cmb_TeamList, js_dep_cd) ;		

    //} 	

};
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    // 유가일때만 디폴트 로그인한 사용자	

    //if (js_market == '1' ) {

    //	setObjectValue(cmb_EmpList, js_emp_no) ;	

    //} 	

};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = cmb_TeamList.ValueOfIndex("VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EmpList, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "사외이사 목록", "", "8");
};
scwin.rdo_MKT_ID_OnSelChange = function() {
    //fn_SetCtrlByMktId();

};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.btn_Upload_onclick = async function() {
    clickId = "upload";
    await $c.frame.CreateDialogFrame("gform", "/dsclmgt/ULDSTF39003.gfm", "사외이사 일괄등록", 200, 100, 590, 270, "window");
};
scwin.btn_Input_onclick = async function() {
    clickId = "input";
    await $c.frame.CreateDialogFrame("gform", "/dsclmgt/ULDSTF39002.gfm", "사외이사 등록", 200, 100, 600, 300, "window");
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch_outside(txb_isur_cd, txb_com_abbrv);
};
scwin.txb_OutDirNm_onkeydown = function() {
    if (window.event.keyCode == "13") {
        fn_Search();
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    // 사외이사 용
    $c.cm.fn_com_isur_outside(txb_isur_cd, txb_com_abbrv);
};
